(()=>{'use strict';const nav=document.querySelector('.ops-nav');if(!nav)return;const box=document.createElement('aside');box.className='work-bar';box.hidden=true;nav.after(box);const action=document.createElement('button'),info=document.createElement('span'),pos=document.createElement('button'),link=document.createElement('a'),people=document.createElement('div'),err=document.createElement('span');people.className='active-people';err.className='work-error';err.setAttribute('role','status');pos.className='pos-toggle';pos.textContent='POS';pos.title='Крупные кнопки для сенсорного экрана';link.textContent='Смены / зарплата';link.href='/admin/workforce/';const account=document.createElement('details'),toggle=document.createElement('summary'),menu=document.createElement('div');account.className='work-account';toggle.textContent='⋯';toggle.setAttribute('aria-label','Смены и учётная запись');menu.append(link);account.append(toggle,menu);box.append(action,info,pos,account,people,err);let data,loading=false,busy=false,pending=null;const rub=n=>(n/100).toLocaleString('ru-RU')+' ₽';
 function mode(v){document.body.classList.toggle('pos-mode',v);pos.setAttribute('aria-pressed',String(v));try{localStorage.setItem('start-pos',v?'1':'0');}catch{}}try{mode(localStorage.getItem('start-pos')===null?matchMedia('(min-width:1000px)').matches:localStorage.getItem('start-pos')==='1');}catch{}pos.onclick=()=>mode(!document.body.classList.contains('pos-mode'));
 async function refresh(){if(document.hidden||loading||busy)return;loading=true;try{const r=await fetch('/api/admin/workforce/current',{cache:'no-store'});if(!r.ok){box.hidden=true;document.body.classList.remove('desk-ready');return;}data=await r.json();box.hidden=false;document.body.classList.add('desk-ready');err.textContent='';action.textContent=data.own?'Ушёл со смены':'Я на смене';info.textContent=data.user.login+(data.own?' · с '+new Date(data.own.started_at).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}):'');people.replaceChildren();for(const p of data.active){const s=document.createElement('span');s.className='work-person';s.textContent=`${p.name} ≈ ${rub(p.salary_cents)}`;s.title=`${Math.floor(p.worked_ms/3600000)} ч ${Math.floor(p.worked_ms/60000)%60} мин на смене`;people.append(s);}people.hidden=false;if(!data.active.length)people.textContent='На смене пока никого';people.title='Предварительный заработок за сегодня. Итог после сверки кассы.';}catch{if(!box.hidden)err.textContent='Не удалось обновить смены. Повторим автоматически.';}finally{loading=false;}}
 action.onclick=async()=>{if(busy||!data)return;busy=true;action.disabled=true;err.textContent='';try{const kind=data.own?'end':'start';if(!pending)pending={kind,body:{requestId:crypto.randomUUID(),...(data.own?{sessionId:data.own.id}:{})}};const r=await fetch('/api/admin/workforce/'+pending.kind,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pending.body)}),d=await r.json();if(!r.ok){if(r.status<500)pending=null;throw Error(d.error);}pending=null;}catch(e){err.textContent=e.message;}finally{busy=false;action.disabled=false;await refresh();}};refresh();setInterval(refresh,30000);document.addEventListener('visibilitychange',refresh);document.addEventListener('station-updated',refresh);document.addEventListener('click',e=>{if(e.target.closest('#login-form button'))setTimeout(refresh,800);});})();
